DROP DATABASE IF EXISTS smart_campus_parking;
CREATE DATABASE smart_campus_parking;
USE smart_campus_parking;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,email VARCHAR(120),role ENUM('Admin','Staff','Student') DEFAULT 'Student',status ENUM('Active','Inactive') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicles(vehicle_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,plate_number VARCHAR(30) UNIQUE NOT NULL,vehicle_type VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE parking_zones(zone_id INT AUTO_INCREMENT PRIMARY KEY,zone_name VARCHAR(60) NOT NULL,total_slots INT NOT NULL,distance_meters INT DEFAULT 0);
CREATE TABLE parking_slots(slot_id INT AUTO_INCREMENT PRIMARY KEY,zone_id INT NOT NULL,slot_code VARCHAR(30) UNIQUE NOT NULL,status ENUM('Available','Occupied','Reserved','Maintenance') DEFAULT 'Available',FOREIGN KEY(zone_id) REFERENCES parking_zones(zone_id));
CREATE TABLE reservations(reservation_id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,slot_id INT NOT NULL,start_time DATETIME NOT NULL,end_time DATETIME NOT NULL,status ENUM('Confirmed','Cancelled','Completed') DEFAULT 'Confirmed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id),FOREIGN KEY(slot_id) REFERENCES parking_slots(slot_id));
CREATE TABLE parking_sessions(session_id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,slot_id INT NOT NULL,entry_time DATETIME NOT NULL,exit_time DATETIME NULL,duration_minutes INT DEFAULT 0,fee_amount DECIMAL(10,2) DEFAULT 0,status ENUM('Active','Completed') DEFAULT 'Active',FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id),FOREIGN KEY(slot_id) REFERENCES parking_slots(slot_id));
CREATE TABLE parking_passes(pass_id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,pass_code VARCHAR(60) UNIQUE NOT NULL,valid_from DATETIME NOT NULL,valid_until DATETIME NOT NULL,status ENUM('Active','Expired','Revoked') DEFAULT 'Active',FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id));
CREATE TABLE payments(payment_id INT AUTO_INCREMENT PRIMARY KEY,session_id INT NULL,violation_id INT NULL,amount DECIMAL(10,2) NOT NULL,payment_method VARCHAR(30) DEFAULT 'Cash',payment_status ENUM('Paid','Pending','Failed') DEFAULT 'Paid',paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE violations(violation_id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,violation_type VARCHAR(100) NOT NULL,fine_amount DECIMAL(10,2) NOT NULL,status ENUM('Unpaid','Paid','Cancelled') DEFAULT 'Unpaid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id));
CREATE TABLE occupancy_records(record_id INT AUTO_INCREMENT PRIMARY KEY,zone_id INT,total_slots INT,occupied_slots INT,recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(zone_id) REFERENCES parking_zones(zone_id));
CREATE TABLE traffic_records(traffic_id INT AUTO_INCREMENT PRIMARY KEY,zone_id INT,congestion_level INT NOT NULL,record_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(zone_id) REFERENCES parking_zones(zone_id));
CREATE TABLE recommendation_logs(log_id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT,slot_id INT,reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE alerts(alert_id INT AUTO_INCREMENT PRIMARY KEY,message VARCHAR(255) NOT NULL,severity VARCHAR(20) DEFAULT 'INFO',is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
