INSERT INTO parking_slots(zone_id,slot_code,status) SELECT z.zone_id,CONCAT(LEFT(z.zone_name,2),LPAD(n.n,2,'0')),'Available' FROM parking_zones z JOIN (SELECT 1 n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12 UNION SELECT 13 UNION SELECT 14 UNION SELECT 15 UNION SELECT 16) n;
