CREATE OR REPLACE VIEW v_zone_status AS SELECT z.zone_name,z.total_slots,SUM(s.status='Available') available_slots,SUM(s.status='Occupied') occupied_slots,ROUND(SUM(s.status='Occupied')/z.total_slots*100,1) utilization_pct FROM parking_zones z JOIN parking_slots s ON z.zone_id=s.zone_id GROUP BY z.zone_id,z.zone_name,z.total_slots;
DROP PROCEDURE IF EXISTS calculate_parking_fee;
DELIMITER //
CREATE PROCEDURE calculate_parking_fee(IN p_session_id INT, OUT p_fee DECIMAL(10,2)) BEGIN DECLARE mins INT; DECLARE sid INT; SELECT TIMESTAMPDIFF(MINUTE,entry_time,NOW()),slot_id INTO mins,sid FROM parking_sessions WHERE session_id=p_session_id AND status='Active'; SET p_fee=ROUND(GREATEST(1,CEIL(IFNULL(mins,0)/60))*30,2); UPDATE parking_sessions SET exit_time=NOW(),duration_minutes=IFNULL(mins,0),fee_amount=p_fee,status='Completed' WHERE session_id=p_session_id; UPDATE parking_slots SET status='Available' WHERE slot_id=sid; INSERT INTO payments(session_id,amount,payment_method,payment_status) VALUES(p_session_id,p_fee,'Cash','Paid'); END//
DELIMITER ;
CREATE OR REPLACE VIEW v_daily_revenue AS SELECT DATE(paid_at) paid_date,SUM(amount) revenue FROM payments WHERE payment_status='Paid' GROUP BY DATE(paid_at);
